"""Prepare three axis-aligned vanilla geometry examples, preserving whole assets.

This is a demo adapter, not an engine geometry/animation/display-transform parser.
It resolves UV corners explicitly; the public cuboid constructor remains generic.
"""
from pathlib import Path
import argparse,hashlib,json,struct,zipfile
ROOT=Path(__file__).resolve().parent.parent
ARCHIVE_SHA='d93dea9aa1fb241a3184cc9f9a074a2ff34bd1b3c00d859b09c24b4b9e4e9adf'
IDS=['shelf_mushroom_small','shelf_mushroom_large','straw_bed_foot']
UV_CORNERS={'east':[(0,0),(0,1),(1,1),(1,0)],'west':[(1,0),(0,0),(0,1),(1,1)],'north':[(1,0),(0,0),(0,1),(1,1)],'south':[(1,0),(0,0),(0,1),(1,1)],'up':[(1,0),(0,0),(0,1),(1,1)],'down':[(0,1),(1,1),(1,0),(0,0)]}
def sha(b):return hashlib.sha256(b).hexdigest()
def generate():
    archive=ROOT/'.cache/references/bedrock-samples-v1.26.60.5-full.zip'
    if sha(archive.read_bytes())!=ARCHIVE_SHA:raise ValueError('Fixed original ZIP identity')
    outputs={};models=[];records=[]
    with zipfile.ZipFile(archive) as z:
        for name in IDS:
            geo_path=f'resource_pack/models/blocks/{name}.geo.json';raw=z.read(geo_path);geometry=json.loads(raw)['minecraft:geometry'][0]
            texture_name='straw_bed' if name=='straw_bed_foot' else name;tex_path=f'resource_pack/textures/blocks/{texture_name}.png';texture=z.read(tex_path);width,height=struct.unpack('>II',texture[16:24]);desc=geometry['description'];sw,sh=desc['texture_width'],desc['texture_height']
            for entry,data,destination in [(geo_path,raw,f'demo/assets/model-source/{name}.geo.json'),(tex_path,texture,f'demo/assets/model-source/{texture_name}.png')]:
                outputs[destination]=data;records.append({'entry':entry,'destination':destination,'bytes':len(data),'sha256':sha(data)})
            boxes=[]
            for bone in geometry['bones']:
                if set(bone)-{'name','cubes'}:raise ValueError('Example adapter requires untransformed bones')
                for cube in bone['cubes']:
                    if set(cube)-{'origin','size','pivot','uv'}:raise ValueError('Example adapter does not ignore cube transforms')
                    x,y,z0=cube['origin'];dx,dy,dz=cube['size'];minimum=[-x-dx,y,z0];maximum=[-x,y+dy,z0+dz];uvs={}
                    for face,uv in cube['uv'].items():
                        if face not in UV_CORNERS or set(uv)-{'uv','uv_size','material_instance','uv_rotation'}:raise ValueError('Unsupported source face')
                        u,v=uv['uv'];du,dv=uv['uv_size']
                        if face in ['up','down']:u,v,du,dv=u+du,v+dv,-du,-dv
                        rotation=uv.get('uv_rotation',0)
                        if rotation not in [0,90,180,270]:raise ValueError('Example adapter requires quarter-turn UV rotation')
                        corners=UV_CORNERS[face]
                        for _ in range(rotation//90):corners=[(b,1-a) for a,b in corners]
                        uvs[face]=[[(u+a*du)*width/sw,(v+b*dv)*height/sh] for a,b in corners]
                    boxes.append({'min':minimum,'max':maximum,'faces':list(uvs),'uvs':uvs})
            models.append({'id':name,'label':name.replace('_',' '),'textureSize':[width,height],'uvSourceSize':[sw,sh],'boxes':boxes,'documentedDisplayTransform':geometry.get('item_display_transforms',{}).get('gui')})
        license_bytes=z.read('LICENSE.md');destination='demo/assets/model-source/Minecraft-Sample-LICENSE.md';outputs[destination]=license_bytes;records.append({'entry':'LICENSE.md','destination':destination,'bytes':len(license_bytes),'sha256':sha(license_bytes)})
    data=json.dumps(models,ensure_ascii=False,indent=2)
    code="// Generated by scripts/prepare-model-source-examples.py. Whole originals, explicit demo UV resolver.\nimport {createGuiCuboidModel} from '../src/gui-model-geometry';\nimport type {GuiCuboidFace,GuiModelItem,GuiModelProjection,GuiTextRgba8} from '../src';\n"
    code+='const records='+data+' as const;\n'
    code+='const sources={'+','.join(json.dumps(n)+':{texture:new URL('+json.dumps('./assets/model-source/'+('straw_bed' if n=='straw_bed_foot' else n)+'.png')+',import.meta.url).href,geometry:new URL('+json.dumps('./assets/model-source/'+n+'.geo.json')+',import.meta.url).href}' for n in IDS)+'};\n'
    code+="const projection:GuiModelProjection={yaw:45,pitch:30,scale:.625,offset:[0,0],originQuantization:'none'};\n"
    code+="const colors:Partial<Record<GuiCuboidFace,GuiTextRgba8>>={up:[255,255,255,0],east:[127,127,127,0],south:[186,186,186,0]};\n"
    code+="export const modelSourceExamples=records.map(record=>{const material=sources[record.id],faces=record.boxes.flatMap(box=>createGuiCuboidModel(box.min,box.max,{coordinateSpace:'model',faces:box.faces,uvs:box.uvs,colors,textures:Object.fromEntries(box.faces.map(face=>[face,'all']))}).faces);const item:GuiModelItem={model:{faces},projection,textureSizes:{all:record.textureSize},textures:{all:material.texture}};return{id:record.id,label:record.label,item,geometryURL:material.geometry,textureURL:material.texture,sourceFaceCount:faces.length,sourceCubeCount:record.boxes.length,documentedDisplayTransform:record.documentedDisplayTransform};});\n"
    outputs['demo/model-source-data.ts']=code.encode()
    manifest={'sourceRelease':'v1.26.60.5','sourceCommit':'15701fa9c13923f12662984c32c124327e40e3d3','archiveSHA256':ARCHIVE_SHA,'resources':records,'models':[{'id':m['id'],'cubes':len(m['boxes']),'faces':sum(len(b['faces']) for b in m['boxes']),'physicalTextureSize':m['textureSize'],'geometryUVSize':m['uvSourceSize'],'itemDisplayTransformsApplied':False} for m in models],'adapterScope':'Axis-aligned eight original cubes only. Mirrored X and explicit per-face UV corners follow Blockbench local convention; texture coordinates scale from declared UV size to original physical PNG size. No animation, bone/cube rotation, item display transforms or fit-to-frame evaluation.','editorSource':'https://github.com/JannisX11/blockbench/tree/ec0b2827104d0799c153bfb5f867579c0c44652f/js','nativeCertified':False}
    outputs['docs/model-source-examples.json']=(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n').encode()
    return outputs
if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--check',action='store_true');args=parser.parse_args()
    for name,data in generate().items():
        target=ROOT/name
        if args.check:
            if not target.exists() or target.read_bytes()!=data:raise ValueError('Generated or original bytes differ: '+name)
        else:target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(data)
    print('Three original models / eight cubes / 35 faces: '+('CHECK' if args.check else 'PREPARED'))
